package android.app.job;import java.util.*;public class JobScheduler {public static final int RESULT_SUCCESS=1;public int schedules;public boolean reject;public final Map<Integer,JobInfo> jobs=new HashMap<>();public JobInfo getPendingJob(int id){return jobs.get(id);}public int schedule(JobInfo i){schedules++;if(reject)return 0;jobs.put(i.id,i);return 1;}public void cancel(int id){jobs.remove(id);}}
